import { FormEvent, ReactNode, useEffect, useState } from 'react'
import {
  AlertTriangle, ArrowLeft, ArrowRight, BarChart3, Boxes, Building2, Check, ClipboardList,
  ChevronDown, ChevronRight, CircleDollarSign, Clock3, LayoutDashboard,
  LogOut, Menu, MoreHorizontal, Package, PackagePlus, Pencil, Plus, RefreshCw, Search,
  Settings, ShoppingBag, Tags, Users, X,
} from 'lucide-react'
import { useLocation, useNavigate } from 'react-router-dom'
import { api, session, SESSION_EXPIRED_EVENT } from './api'
import { AuditPage, CustomerDetail, CustomersPage, InventoryPage, NewOrderPage, OrderDetail, OrdersPage } from './Operations'
import type { DataState, InventoryMovement, Offer, PricingBreakdown, PricingRules, Product, ProductMedia, Reference, Supplier, Variant } from './types'

type View = 'dashboard' | 'products' | 'product' | 'product-edit' | 'sku' | 'new-product' | 'brands' | 'categories' | 'suppliers' | 'supplier' | 'prices' | 'inventory' | 'customers' | 'customer' | 'orders' | 'new-order' | 'order' | 'settings' | 'audit'
type ToastKind = 'success' | 'error'
type Toast = { kind: ToastKind; message: string } | null
type RouteState = { view: View; productId?: string; variantId?: string; supplierId?: string; customerId?: string; orderId?: string; valid: boolean }

const STATIC_PATHS: Partial<Record<View, string>> = {
  dashboard: '/',
  products: '/catalogo/productos',
  'new-product': '/catalogo/productos/nuevo',
  categories: '/catalogo/categorias',
  brands: '/catalogo/marcas',
  suppliers: '/proveedores',
  prices: '/precios',
  inventory: '/inventario',
  customers: '/clientes',
  orders: '/pedidos',
  'new-order': '/pedidos/nuevo',
  settings: '/configuracion',
  audit: '/configuracion/auditoria',
}

const readRoute = (pathname: string): RouteState => {
  const path = pathname.length > 1 ? pathname.replace(/\/$/, '') : pathname
  const skuMatch = path.match(/^\/catalogo\/productos\/([^/]+)\/variantes\/([^/]+)$/)
  if (skuMatch) return { view: 'sku', productId: decodeURIComponent(skuMatch[1]), variantId: decodeURIComponent(skuMatch[2]), valid: true }
  const editMatch = path.match(/^\/catalogo\/productos\/([^/]+)\/editar$/)
  if (editMatch) return { view: 'product-edit', productId: decodeURIComponent(editMatch[1]), valid: true }
  const productMatch = path.match(/^\/catalogo\/productos\/([^/]+)$/)
  if (productMatch && productMatch[1] !== 'nuevo') return { view: 'product', productId: decodeURIComponent(productMatch[1]), valid: true }
  const supplierMatch = path.match(/^\/proveedores\/([^/]+)$/)
  if (supplierMatch) return { view: 'supplier', supplierId: decodeURIComponent(supplierMatch[1]), valid: true }
  const customerMatch = path.match(/^\/clientes\/([^/]+)$/)
  if (customerMatch && customerMatch[1] !== 'nuevo') return { view: 'customer', customerId: decodeURIComponent(customerMatch[1]), valid: true }
  const orderMatch = path.match(/^\/pedidos\/([^/]+)$/)
  if (orderMatch && orderMatch[1] !== 'nuevo') return { view: 'order', orderId: decodeURIComponent(orderMatch[1]), valid: true }
  const staticRoute = Object.entries(STATIC_PATHS).find(([, routePath]) => routePath === path)
  return staticRoute ? { view: staticRoute[0] as View, valid: true } : { view: 'dashboard', valid: false }
}

const money = (value: string | number | null | undefined) => value == null || value === '' ? '—' : new Intl.NumberFormat('es-AR', { style: 'currency', currency: 'ARS', maximumFractionDigits: 0 }).format(Number(value))
const percentage = (value: number | null) => value == null || !Number.isFinite(value) ? '—' : `${value.toFixed(1).replace('.', ',')}%`
const getPreferredOffer = (variant: Variant, offers: Offer[]) => offers.find((offer) => offer.id === variant.preferredSupplierOfferId) || offers.find((offer) => offer.variantId === variant.id && offer.stockStatus === 'AVAILABLE') || offers.find((offer) => offer.variantId === variant.id)
const marginFor = (variant: Variant, offers: Offer[]) => {
  const offer = getPreferredOffer(variant, offers)
  if (!offer || !variant.salePrice || Number(variant.salePrice) <= 0) return null
  return ((Number(variant.salePrice) - Number(offer.unitCost)) / Number(variant.salePrice)) * 100
}
const recommendedFor = (variant: Variant, offers: Offer[], data: DataState) => {
  const offer = getPreferredOffer(variant, offers); const rules = data.rules.active
  if (!offer || !rules) return null
  const base = Number(offer.unitCost) + Number(rules.fulfillmentCost || 0) + Number(rules.packagingCost || 0) + Number(rules.paymentFixedCost || 0) + Number(rules.subsidizedShippingCost || 0) + Number(rules.otherCost || 0)
  const rate = (Number(rules.paymentFeePercent || 0) + Number(rules.taxPercent || 0) + Number(rules.targetMarginPercent || 0)) / 100
  const exact = base / Math.max(.01, 1 - rate)
  return Math.ceil(exact / 10) * 10 - 10
}
const commercialFor = (recommended: number) => {
  let candidate = Math.floor(recommended / 1000) * 1000 + 990
  if (candidate < recommended) candidate += 1000
  return candidate
}
const allowedImageTypes = new Set(['image/jpeg', 'image/png', 'image/webp', 'image/gif'])
const imageFileError = (file: File) => !allowedImageTypes.has(file.type)
  ? 'El archivo debe ser JPEG, PNG, WebP o GIF.'
  : file.size > 10 * 1024 * 1024 ? 'La imagen no puede superar los 10 MB.' : null
const formatPresentation = (presentation: string | null, weightGrams?: number | null) => {
  const raw = presentation || (weightGrams ? `${weightGrams} g` : '')
  const match = raw.trim().match(/^(\d+)\s*g$/i)
  if (!match) return raw || 'Sin presentación'
  const grams = Number(match[1])
  return grams >= 1000 ? `${new Intl.NumberFormat('es-AR', { maximumFractionDigits: 2 }).format(grams / 1000)} kg` : `${grams} g`
}

export default function App() {
  const location = useLocation()
  const routerNavigate = useNavigate()
  const route = readRoute(location.pathname)
  const [authenticated, setAuthenticated] = useState(Boolean(session.get()))
  const [data, setData] = useState<DataState | null>(null)
  const [loading, setLoading] = useState(false)
  const [toast, setToast] = useState<Toast>(null)
  const [mobileNav, setMobileNav] = useState(false)

  const load = async () => {
    setLoading(true)
    try { setData(await api.loadAll()) }
    catch (error) {
      const status = (error as Error & { status?: number }).status
      if (status === 401 || status === 403) { session.clear(); setAuthenticated(false) }
      setToast({ kind: 'error', message: (error as Error).message })
    } finally { setLoading(false) }
  }
  useEffect(() => { if (authenticated) void load() }, [authenticated])
  useEffect(() => { if (!toast) return; const id = window.setTimeout(() => setToast(null), 4200); return () => window.clearTimeout(id) }, [toast])
  useEffect(() => {
    const handleExpiredSession = () => {
      setData(null)
      setAuthenticated(false)
      routerNavigate('/login', { replace: true })
    }
    window.addEventListener(SESSION_EXPIRED_EVENT, handleExpiredSession)
    return () => window.removeEventListener(SESSION_EXPIRED_EVENT, handleExpiredSession)
  }, [routerNavigate])
  useEffect(() => {
    if (!authenticated && location.pathname !== '/login') routerNavigate('/login', { replace: true })
    if (authenticated && location.pathname === '/login') routerNavigate('/', { replace: true })
  }, [authenticated, location.pathname, routerNavigate])
  useEffect(() => {
    if (authenticated && location.pathname !== '/login' && !route.valid) routerNavigate('/', { replace: true })
  }, [authenticated, location.pathname, route.valid, routerNavigate])

  const navigate = (next: View) => {
    let path = STATIC_PATHS[next]
    if (next === 'product' && route.productId) path = `/catalogo/productos/${encodeURIComponent(route.productId)}`
    if (next === 'product-edit' && route.productId) path = `/catalogo/productos/${encodeURIComponent(route.productId)}/editar`
    if (path) routerNavigate(path)
    setMobileNav(false)
    window.scrollTo({ top: 0, behavior: 'smooth' })
  }
  const openProduct = (id: string) => { routerNavigate(`/catalogo/productos/${encodeURIComponent(id)}`); setMobileNav(false) }
  const editProduct = (id: string) => routerNavigate(`/catalogo/productos/${encodeURIComponent(id)}/editar`)
  const openVariant = (id: string, productId?: string) => {
    const ownerId = productId || data?.products.find((product) => product.variants.some((variant) => variant.id === id))?.id
    if (ownerId) routerNavigate(`/catalogo/productos/${encodeURIComponent(ownerId)}/variantes/${encodeURIComponent(id)}`)
    setMobileNav(false)
  }
  const openSupplier = (id: string) => { routerNavigate(`/proveedores/${encodeURIComponent(id)}`); setMobileNav(false) }
  const openCustomer = (id: string) => { routerNavigate(`/clientes/${encodeURIComponent(id)}`); setMobileNav(false) }
  const openOrder = (id: string) => { routerNavigate(`/pedidos/${encodeURIComponent(id)}`); setMobileNav(false) }
  const notify = (message: string, kind: ToastKind = 'success') => setToast({ kind, message })
  const mutate = (recipe: (current: DataState) => DataState) => setData((current) => current ? recipe(current) : current)

  if (!authenticated) return <Login onAuthenticated={() => setAuthenticated(true)} />
  if (!data) return <LoadingScreen />
  const selectedProduct = data.products.find((product) => product.id === route.productId) || null
  const selectedVariant = data.products.flatMap((product) => product.variants).find((variant) => variant.id === route.variantId) || null
  const selectedSupplier = data.suppliers.find((supplier) => supplier.id === route.supplierId) || null
  const view = route.view

  return (
    <div className="app-shell">
      <Sidebar view={view} open={mobileNav} navigate={navigate} onClose={() => setMobileNav(false)} />
      <div className="app-main">
        <Topbar onMenu={() => setMobileNav(true)} onLogout={() => { session.clear(); setAuthenticated(false); setData(null); routerNavigate('/login', { replace: true }) }} />
        <main className="content">
          {loading && <div className="loading-bar" />}
          {view === 'dashboard' && <Dashboard data={data} navigate={navigate} openVariant={openVariant} />}
          {view === 'products' && <Products data={data} openProduct={openProduct} editProduct={editProduct} openVariant={openVariant} navigate={navigate} />}
          {(view === 'product' || view === 'product-edit') && selectedProduct && <ProductDetail product={selectedProduct} data={data} editingFromRoute={view === 'product-edit'} navigate={navigate} editProduct={editProduct} openVariant={openVariant} mutate={mutate} notify={notify} />}
          {view === 'sku' && selectedVariant && <SkuDetail variant={selectedVariant} data={data} navigate={navigate} mutate={mutate} notify={notify} />}
          {view === 'new-product' && <NewProduct data={data} navigate={navigate} mutate={mutate} notify={notify} openProduct={openProduct} />}
          {(view === 'brands' || view === 'categories') && <References type={view} data={data} mutate={mutate} notify={notify} />}
          {view === 'suppliers' && <Suppliers data={data} mutate={mutate} notify={notify} openSupplier={openSupplier} />}
          {view === 'supplier' && selectedSupplier && <SupplierDetail supplier={selectedSupplier} data={data} navigate={navigate} openVariant={openVariant} mutate={mutate} notify={notify} />}
          {view === 'prices' && <Prices data={data} mutate={mutate} notify={notify} openVariant={openVariant} />}
          {view === 'inventory' && <InventoryPage notify={notify} openVariant={openVariant} />}
          {view === 'customers' && <CustomersPage notify={notify} openCustomer={openCustomer} />}
          {view === 'customer' && route.customerId && <CustomerDetail id={route.customerId} notify={notify} back={() => navigate('customers')} openOrder={openOrder} />}
          {view === 'orders' && <OrdersPage openOrder={openOrder} newOrder={() => navigate('new-order')} />}
          {view === 'new-order' && <NewOrderPage data={data} notify={notify} back={() => navigate('orders')} openOrder={openOrder} />}
          {view === 'order' && route.orderId && <OrderDetail id={route.orderId} notify={notify} back={() => navigate('orders')} />}
          {view === 'settings' && <PricingSettings data={data} mutate={mutate} notify={notify} />}
          {view === 'audit' && <AuditPage />}
          {((view === 'product' || view === 'product-edit') && !selectedProduct) || (view === 'sku' && !selectedVariant) || (view === 'supplier' && !selectedSupplier) ? <NotFound navigate={navigate} /> : null}
        </main>
      </div>
      {toast && <div className={`toast ${toast.kind}`}><span>{toast.kind === 'success' ? <Check size={17} /> : <AlertTriangle size={17} />}</span>{toast.message}<button onClick={() => setToast(null)}><X size={15} /></button></div>}
    </div>
  )
}

function Login({ onAuthenticated }: { onAuthenticated: () => void }) {
  const [email, setEmail] = useState(''); const [password, setPassword] = useState(''); const [busy, setBusy] = useState(false); const [error, setError] = useState('')
  const submit = async (event: FormEvent) => {
    event.preventDefault(); setBusy(true); setError('')
    try {
      const result = await api.login(email, password)
      if (!result.session?.accessToken || result.user?.role !== 'ADMIN') throw new Error('Esta cuenta no tiene acceso al backoffice.')
      session.set(result.session); onAuthenticated()
    } catch (cause) { setError((cause as Error).message) } finally { setBusy(false) }
  }
  return <div className="login-page">
    <section className="login-brand"><div className="brand-mark large"><img src="/brand/patitas-isotipo.png" alt="Patitas Inquietas" /></div><div><p className="eyebrow light">Patitas Backoffice</p><h1>Todo el negocio,<br />sin abrir una planilla.</h1><p>Catálogo, proveedores y precios conectados en un solo flujo operativo.</p></div><div className="login-proof"><span><Check size={15} /> Precio recomendado al instante</span><span><Check size={15} /> Margen y costos siempre visibles</span></div></section>
    <section className="login-panel"><form onSubmit={submit} className="login-card"><div><p className="eyebrow">Acceso operativo</p><h2>Ingresá a Patitas</h2><p className="muted">Usá tu cuenta administradora de la API.</p></div><label>Email<input autoFocus type="email" value={email} onChange={(e) => setEmail(e.target.value)} placeholder="nombre@patitas.com" required /></label><label>Contraseña<input type="password" value={password} onChange={(e) => setPassword(e.target.value)} placeholder="••••••••" minLength={8} required /></label>{error && <div className="inline-error"><AlertTriangle size={16} />{error}</div>}<button className="button primary full" disabled={busy}>{busy ? 'Ingresando…' : <>Ingresar <ArrowRight size={17} /></>}</button><small>API: localhost:3000/api/v1</small></form></section>
  </div>
}

function Sidebar({ view, open, navigate, onClose }: { view: View; open: boolean; navigate: (view: View) => void; onClose: () => void }) {
  const [catalogOpen, setCatalogOpen] = useState(true)
  const item = (target: View, icon: ReactNode, label: string, sub = false) => <button className={`nav-item ${sub ? 'sub' : ''} ${view === target ? 'active' : ''}`} onClick={() => navigate(target)}>{icon}<span>{label}</span></button>
  return <><aside className={`sidebar ${open ? 'open' : ''}`}><div className="sidebar-head"><img className="sidebar-logo" src="/brand/patitas-logo-horizontal.png" alt="Patitas Inquietas" /><span className="backoffice-label">Backoffice</span><button className="mobile-close" onClick={onClose}><X size={20} /></button></div><nav>
    {item('dashboard', <LayoutDashboard size={18} />, 'Dashboard')}
    <button className={`nav-item ${['products', 'product', 'product-edit', 'sku', 'new-product', 'brands', 'categories'].includes(view) ? 'parent-active' : ''}`} onClick={() => setCatalogOpen(!catalogOpen)}><Package size={18} /><span>Catálogo</span><ChevronDown className={catalogOpen ? 'rotated' : ''} size={15} /></button>
    {catalogOpen && <div className="nav-group">{item('products', null, 'Productos', true)}{item('categories', null, 'Categorías', true)}{item('brands', null, 'Marcas', true)}</div>}
    {item('suppliers', <Building2 size={18} />, 'Proveedores')}
    {item('prices', <CircleDollarSign size={18} />, 'Precios')}
    <div className="nav-separator" />
    {item('inventory', <Boxes size={18} />, 'Inventario')}{item('orders', <ShoppingBag size={18} />, 'Pedidos')}{item('customers', <Users size={18} />, 'Clientes')}
  </nav><div className="sidebar-foot">{item('settings', <Settings size={18} />, 'Configuración')}<button className={`nav-item ${view === 'audit' ? 'active' : ''}`} onClick={() => navigate('audit')}><ClipboardList size={18} /><span>Auditoría</span></button></div></aside>{open && <div className="backdrop" onClick={onClose} />}</>
}

function Topbar({ onMenu, onLogout }: { onMenu: () => void; onLogout: () => void }) {
  return <header className="topbar"><button className="menu-button" onClick={onMenu}><Menu size={21} /></button><div className="environment"><span />API conectada</div><div className="top-actions"><div className="avatar">AS</div><div className="user-meta"><strong>Operaciones</strong><span>Administrador</span></div><button className="icon-button" title="Cerrar sesión" onClick={onLogout}><LogOut size={18} /></button></div></header>
}

function PageHeader({ eyebrow, title, description, actions, back }: { eyebrow?: string; title: string; description?: string; actions?: ReactNode; back?: () => void }) {
  return <div className="page-header"><div className="title-row">{back && <button className="back-button" onClick={back}><ArrowLeft size={19} /></button>}<div>{eyebrow && <p className="eyebrow">{eyebrow}</p>}<h1>{title}</h1>{description && <p>{description}</p>}</div></div>{actions && <div className="header-actions">{actions}</div>}</div>
}

function Dashboard({ data, navigate, openVariant }: { data: DataState; navigate: (view: View) => void; openVariant: (id: string, productId?: string) => void }) {
  const variants = data.products.flatMap((p) => p.variants.map((v) => ({ ...v, product: p })))
  const active = data.products.filter((p) => p.status === 'ACTIVE').length
  const withoutPrice = variants.filter((v) => !v.salePrice).length
  const noSupplier = variants.filter((v) => !data.offers.some((o) => o.variantId === v.id && o.stockStatus === 'AVAILABLE')).length
  const target = Number(data.rules.active?.targetMarginPercent || 25)
  const margins = variants.map((v) => marginFor(v, data.offers)).filter((v): v is number => v !== null)
  const lowMargin = variants.filter((v) => { const margin = marginFor(v, data.offers); return margin !== null && margin < target })
  const metrics = [{ label: 'Productos activos', value: active, hint: `${data.products.length} en catálogo`, tone: 'neutral' }, { label: 'Productos sin precio', value: withoutPrice, hint: withoutPrice ? 'Requieren atención' : 'Todo en orden', tone: withoutPrice ? 'warning' : 'success' }, { label: 'Precios a revisar', value: lowMargin.length, hint: `Margen objetivo ${target}%`, tone: lowMargin.length ? 'warning' : 'success' }, { label: 'Sin proveedor', value: noSupplier, hint: 'Sin oferta disponible', tone: noSupplier ? 'danger' : 'success' }, { label: 'Margen promedio', value: percentage(margins.length ? margins.reduce((a, b) => a + b, 0) / margins.length : null), hint: 'Sobre costo mercadería', tone: 'success' }]
  return <><PageHeader eyebrow="Resumen operativo" title="Buen día" description="Esto es lo que requiere tu atención hoy." actions={<button className="button primary" onClick={() => navigate('new-product')}><Plus size={17} /> Nuevo producto</button>} />
    <div className="metrics-grid">{metrics.map((metric) => <div className="metric-card" key={metric.label}><div className="metric-label"><span>{metric.label}</span><MoreHorizontal size={17} /></div><strong>{metric.value}</strong><small className={metric.tone}>{metric.tone === 'success' && <Check size={13} />}{metric.hint}</small></div>)}</div>
    <div className="dashboard-grid"><section className="panel alerts-panel"><div className="panel-heading"><div><h2>Alertas</h2><p>Prioridades que impactan tus ventas.</p></div><span className="count-badge">{lowMargin.length + noSupplier}</span></div><div className="alerts-list">{lowMargin.slice(0, 3).map((item) => <button key={item.id} onClick={() => openVariant(item.id, item.product.id)}><span className="alert-icon warning"><AlertTriangle size={18} /></span><span><strong>{item.product.name} · {item.presentation}</strong><small>Margen de {percentage(marginFor(item, data.offers))}, por debajo del objetivo.</small></span><ChevronRight size={17} /></button>)}{noSupplier > 0 && <button onClick={() => navigate('products')}><span className="alert-icon danger"><Building2 size={18} /></span><span><strong>{noSupplier} SKU{noSupplier > 1 ? 's' : ''} sin proveedor disponible</strong><small>No se pueden reponer hasta asociar una oferta.</small></span><ChevronRight size={17} /></button>}{lowMargin.length + noSupplier === 0 && <div className="empty-state compact"><Check size={24} /><strong>Todo bajo control</strong><p>No hay alertas operativas por ahora.</p></div>}</div></section>
      <section className="panel quick-panel"><div className="panel-heading"><div><h2>Accesos rápidos</h2><p>Operaciones frecuentes.</p></div></div><button onClick={() => navigate('new-product')}><span><PackagePlus size={19} /></span><div><strong>Crear producto</strong><small>Producto, variante y proveedor</small></div><ChevronRight size={17} /></button><button onClick={() => navigate('prices')}><span><CircleDollarSign size={19} /></span><div><strong>Revisar precios</strong><small>{lowMargin.length} pendientes</small></div><ChevronRight size={17} /></button><button onClick={() => navigate('suppliers')}><span><Building2 size={19} /></span><div><strong>Ver proveedores</strong><small>{data.suppliers.filter((s) => s.active).length} activos</small></div><ChevronRight size={17} /></button></section>
    </div>
    <section className="panel recent"><div className="panel-heading"><div><h2>Catálogo</h2><p>Vista rápida de productos recientes.</p></div><button className="text-button" onClick={() => navigate('products')}>Ver catálogo <ArrowRight size={16} /></button></div><ProductTable rows={variants.slice(0, 5)} data={data} openVariant={openVariant} /></section>
  </>
}

function Products({ data, openProduct, editProduct, openVariant, navigate }: { data: DataState; openProduct: (id: string) => void; editProduct: (id: string) => void; openVariant: (id: string, productId?: string) => void; navigate: (view: View) => void }) {
  const [query, setQuery] = useState(''); const [species, setSpecies] = useState(''); const [category, setCategory] = useState(''); const [brand, setBrand] = useState(''); const [status, setStatus] = useState('')
  const filtered = data.products.filter((p) => (!query || `${p.name} ${p.variants.map(v => v.sku).join(' ')}`.toLowerCase().includes(query.toLowerCase())) && (!species || p.species === species) && (!category || p.categoryId === category) && (!brand || p.brandId === brand) && (!status || p.status === status))
  const rows = filtered.flatMap((p) => p.variants.length ? p.variants.map((v) => ({ ...v, product: p })) : [{ id: `empty-${p.id}`, productId: p.id, sku: null, presentation: null, weightGrams: null, salePrice: null, compareAtPrice: null, active: false, preferredSupplierOfferId: null, revision: 0, product: p }])
  return <><PageHeader eyebrow="Catálogo" title="Productos" description={`${data.products.length} productos · ${data.products.flatMap(p => p.variants).length} SKU`} actions={<button className="button primary" onClick={() => navigate('new-product')}><Plus size={17} /> Nuevo producto</button>} />
    <section className="panel table-panel"><div className="filters"><label className="search-field"><Search size={17} /><input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Buscar producto o SKU" /></label><Select value={species} onChange={setSpecies} options={[['', 'Perro / Gato'], ['Perro', 'Perro'], ['Gato', 'Gato']]} /><Select value={category} onChange={setCategory} options={[['', 'Categoría'], ...data.categories.map((x) => [x.id, x.name])]} /><Select value={brand} onChange={setBrand} options={[['', 'Marca'], ...data.brands.map((x) => [x.id, x.name])]} /><Select value={status} onChange={setStatus} options={[['', 'Estado'], ['ACTIVE', 'Activo'], ['DRAFT', 'Borrador'], ['ARCHIVED', 'Archivado']]} /></div>
    <ProductTable rows={rows} data={data} openVariant={openVariant} openProduct={openProduct} editProduct={editProduct} />{rows.length === 0 && <div className="empty-state"><Search size={28} /><strong>Sin resultados</strong><p>Probá cambiando o limpiando los filtros.</p></div>}</section></>
}

function ProductTable({ rows, data, openVariant, openProduct, editProduct }: { rows: (Variant & { product: Product })[]; data: DataState; openVariant: (id: string, productId?: string) => void; openProduct?: (id: string) => void; editProduct?: (id: string) => void }) {
  return <div className="table-wrap"><table><thead><tr><th>Producto</th><th>Marca</th><th>Variante</th><th>Precio</th><th>Margen</th><th>Estado</th><th /></tr></thead><tbody>{rows.map((row) => { const margin = marginFor(row, data.offers); return <tr key={row.id} onClick={() => row.id.startsWith('empty-') ? openProduct?.(row.product.id) : openVariant(row.id, row.product.id)}><td><div className="product-cell"><span className="product-thumb"><Package size={19} /></span><span><strong>{row.product.name}</strong><small>{row.sku || 'Sin SKU'}</small></span></div></td><td>{row.product.brand.name}</td><td>{formatPresentation(row.presentation, row.weightGrams)}</td><td className="strong-cell">{money(row.salePrice)}</td><td><span className={margin !== null && margin < Number(data.rules.active?.targetMarginPercent || 25) ? 'danger-text' : ''}>{percentage(margin)}</span></td><td><StatusBadge status={row.product.status} /></td><td>{editProduct ? <button className="icon-button table-edit" title="Editar información del producto" aria-label={`Editar ${row.product.name}`} onClick={(event) => { event.stopPropagation(); editProduct(row.product.id) }}><Pencil size={16} /></button> : <ChevronRight size={17} />}</td></tr>})}</tbody></table></div>
}

function ProductDetail({ product, data, editingFromRoute, navigate, editProduct, openVariant, mutate, notify }: { product: Product; data: DataState; editingFromRoute: boolean; navigate: (view: View) => void; editProduct: (id: string) => void; openVariant: (id: string, productId?: string) => void; mutate: (fn: (d: DataState) => DataState) => void; notify: (m: string, k?: ToastKind) => void }) {
  const [editing, setEditing] = useState(editingFromRoute); const [addingVariant, setAddingVariant] = useState(false); const [addingMedia, setAddingMedia] = useState(false); const [editingGuide, setEditingGuide] = useState(false); const [busy, setBusy] = useState(false)
  const [form, setForm] = useState({ name: product.name, brandId: product.brandId, categoryId: product.categoryId || '', species: product.species || '', line: product.line || '', lifeStage: product.lifeStage || '', breedSize: product.breedSize || '', description: product.description || '', featuredRank: product.featuredRank?.toString() || '', status: product.status })
  const [variantForm, setVariantForm] = useState({ sku: '', presentation: '', weightGrams: '', active: true })
  const [mediaForm, setMediaForm] = useState<{ file: File | null; altText: string; variantId: string; displayOrder: string }>({ file: null, altText: '', variantId: '', displayOrder: '0' })
  const [editingMedia, setEditingMedia] = useState<ProductMedia | null>(null)
  const [mediaEditForm, setMediaEditForm] = useState({ altText: '', variantId: '', displayOrder: '0' })
  const [guideForm, setGuideForm] = useState({ sourceLabel: '', sourceUrl: '', entries: [{ petWeightKg: '', lifeStage: '', dailyGramsMin: '', dailyGramsMax: '' }] })
  const sellableVariants = product.variants.filter((item) => item.active && Boolean(item.sku) && Number(item.salePrice) > 0)
  const publishChecks = [{ label: 'Marca y categoría activas', ready: Boolean(product.brand.active && product.category?.active) }, { label: 'Al menos una imagen', ready: Boolean(product.media?.some((item) => item.url.trim())) }, { label: 'SKU activo con código y precio', ready: sellableVariants.length > 0 }, { label: 'Stock u oferta con fulfillment', ready: sellableVariants.some((item) => Number(item.availableQuantity || 0) > 0 || data.offers.some((offer) => offer.variantId === item.id && ['AVAILABLE', 'ON_REQUEST'].includes(offer.stockStatus))) }]
  const publishReady = publishChecks.every((item) => item.ready)
  useEffect(() => { setEditing(editingFromRoute) }, [editingFromRoute])
  const openEditing = () => { setEditing(true); editProduct(product.id) }
  const closeEditing = () => { setEditing(false); navigate('product') }
  const replaceProduct = (updated: Product) => mutate((current) => ({ ...current, products: current.products.map((item) => item.id === product.id ? updated : item) }))
  const saveProduct = async (event: FormEvent) => { event.preventDefault(); setBusy(true); try { const payload = { name: form.name, brandId: form.brandId, categoryId: form.categoryId, species: form.species || null, line: form.line || null, lifeStage: form.lifeStage || null, breedSize: form.breedSize || null, description: form.description || null, featuredRank: form.featuredRank ? Number(form.featuredRank) : null, status: form.status }; const updated = await api.updateProduct(product.id, payload); replaceProduct(updated); closeEditing(); notify('Producto actualizado correctamente.') } catch (error) { notify((error as Error).message, 'error') } finally { setBusy(false) } }
  const changeStatus = async (status: Product['status']) => { setBusy(true); try { const updated = await api.updateProduct(product.id, { status }); replaceProduct(updated); setForm((current) => ({ ...current, status })); notify(status === 'ACTIVE' ? 'Producto activado y disponible para publicación.' : status === 'DRAFT' ? 'Producto pasado a borrador.' : 'Producto archivado.') } catch (error) { notify((error as Error).message, 'error') } finally { setBusy(false) } }
  const addVariant = async (event: FormEvent) => { event.preventDefault(); setBusy(true); try { const payload = { sku: variantForm.sku || undefined, presentation: variantForm.presentation || undefined, weightGrams: variantForm.weightGrams ? Number(variantForm.weightGrams) : undefined, active: variantForm.active }; const created = await api.createVariant(product.id, payload); replaceProduct({ ...product, variants: [...product.variants, created] }); setVariantForm({ sku: '', presentation: '', weightGrams: '', active: true }); setAddingVariant(false); notify('Variante agregada. Ya podés asociarle un proveedor.') } catch (error) { notify((error as Error).message, 'error') } finally { setBusy(false) } }
  const addMedia = async (event: FormEvent) => { event.preventDefault(); if (!mediaForm.file) return; setBusy(true); try { const input = { file: mediaForm.file, altText: mediaForm.altText, variantId: mediaForm.variantId || null, displayOrder: Number(mediaForm.displayOrder || 0) }; const created = await api.uploadProductMedia(product.id, input); replaceProduct({ ...product, media: [...(product.media || []), created] }); setMediaForm({ file: null, altText: '', variantId: '', displayOrder: '0' }); setAddingMedia(false); notify('Imagen subida y asociada al producto.') } catch (error) { notify((error as Error).message, 'error') } finally { setBusy(false) } }
  const startMediaEdit = (media: ProductMedia) => { setEditingMedia(media); setMediaEditForm({ altText: media.altText, variantId: media.variantId || '', displayOrder: String(media.displayOrder) }) }
  const saveMedia = async (event: FormEvent) => { event.preventDefault(); if (!editingMedia) return; setBusy(true); try { const payload = { altText: mediaEditForm.altText, variantId: mediaEditForm.variantId || null, displayOrder: Number(mediaEditForm.displayOrder || 0) }; const updated = await api.updateProductMedia(product.id, editingMedia.id, payload); replaceProduct({ ...product, media: (product.media || []).map((media) => media.id === updated.id ? updated : media) }); setEditingMedia(null); notify('Información de la imagen actualizada.') } catch (error) { notify((error as Error).message, 'error') } finally { setBusy(false) } }
  const deleteMedia = async (media: ProductMedia) => { if (!window.confirm('¿Eliminar esta imagen del producto?')) return; setBusy(true); try { await api.deleteProductMedia(product.id, media.id); replaceProduct({ ...product, media: (product.media || []).filter((item) => item.id !== media.id) }); if (editingMedia?.id === media.id) setEditingMedia(null); notify('Imagen eliminada.') } catch (error) { notify((error as Error).message, 'error') } finally { setBusy(false) } }
  const saveGuide = async (event: FormEvent) => { event.preventDefault(); setBusy(true); try { const entries = guideForm.entries.map((entry) => ({ petWeightKg: Number(entry.petWeightKg), lifeStage: entry.lifeStage || null, conditions: {}, dailyGramsMin: Number(entry.dailyGramsMin), dailyGramsMax: Number(entry.dailyGramsMax) })); await api.replaceFeedingGuide(product.id, { sourceLabel: guideForm.sourceLabel, sourceUrl: guideForm.sourceUrl || null, entries }); setEditingGuide(false); notify(`Guía de alimentación guardada con ${entries.length} tramo${entries.length === 1 ? '' : 's'}.`) } catch (error) { notify((error as Error).message, 'error') } finally { setBusy(false) } }
  return <><PageHeader eyebrow="Producto" title={product.name} description={`${product.brand.name} · ${product.category?.name || 'Sin categoría'}`} back={() => navigate('products')} actions={<><StatusBadge status={product.status} />{product.status !== 'ACTIVE' && <button className="button primary" disabled={busy || !publishReady} title={!publishReady ? 'Completá los requisitos de publicación' : undefined} onClick={() => void changeStatus('ACTIVE')}><Check size={16} /> Activar producto</button>}{product.status === 'ACTIVE' && <button className="button secondary" disabled={busy} onClick={() => void changeStatus('DRAFT')}>Pasar a borrador</button>}<button className="button secondary" onClick={editing ? closeEditing : openEditing}><Pencil size={16} /> {editing ? 'Cerrar edición' : 'Editar información'}</button></>} />
    {product.status !== 'ACTIVE' && <section className="panel readiness"><div><strong>Requisitos para activar</strong><span>{publishReady ? 'El producto está listo para publicarse.' : 'Completá los puntos pendientes.'}</span></div>{publishChecks.map((item) => <span className={item.ready ? 'ready' : 'pending'} key={item.label}>{item.ready ? <Check size={14} /> : <AlertTriangle size={14} />}{item.label}</span>)}</section>}
    {editing && <form className="panel edit-panel" onSubmit={saveProduct}><div className="panel-heading"><div><h2>Editar producto</h2><p>Información comercial y estado de publicación.</p></div><button type="button" className="icon-button" onClick={closeEditing}><X size={18} /></button></div><div className="form-grid edit-grid"><Field label="Nombre"><input value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} required /></Field><Field label="Marca"><select value={form.brandId} onChange={(e) => setForm({ ...form, brandId: e.target.value })}>{data.brands.map((item) => <option value={item.id} key={item.id}>{item.name}</option>)}</select></Field><Field label="Categoría"><select value={form.categoryId} onChange={(e) => setForm({ ...form, categoryId: e.target.value })}>{data.categories.map((item) => <option value={item.id} key={item.id}>{item.name}</option>)}</select></Field><Field label="Especie"><select value={form.species} onChange={(e) => setForm({ ...form, species: e.target.value })}><option value="">Sin especificar</option><option>Perro</option><option>Gato</option></select></Field><Field label="Línea"><input value={form.line} onChange={(e) => setForm({ ...form, line: e.target.value })} placeholder="Ej. Adult" /></Field><Field label="Etapa de vida"><input value={form.lifeStage} onChange={(e) => setForm({ ...form, lifeStage: e.target.value })} placeholder="Ej. Adulto" /></Field><Field label="Tamaño de raza"><input value={form.breedSize} onChange={(e) => setForm({ ...form, breedSize: e.target.value })} placeholder="Ej. Mediana" /></Field><Field label="Orden destacado"><input inputMode="numeric" value={form.featuredRank} onChange={(e) => setForm({ ...form, featuredRank: e.target.value.replace(/\D/g, '') })} placeholder="Vacío = no destacado" /></Field><Field label="Estado"><select value={form.status} onChange={(e) => setForm({ ...form, status: e.target.value as Product['status'] })}><option value="DRAFT">Borrador</option><option value="ACTIVE">Activo</option><option value="ARCHIVED">Archivado</option></select></Field><Field label="Descripción" wide><textarea rows={4} value={form.description} onChange={(e) => setForm({ ...form, description: e.target.value })} /></Field></div><div className="form-actions"><button type="button" className="button ghost" onClick={closeEditing}>Cancelar</button><button className="button primary" disabled={busy}>{busy ? 'Guardando…' : 'Guardar cambios'}</button></div></form>}
    {addingMedia && <form className="panel edit-panel" onSubmit={addMedia}><div className="panel-heading"><div><h2>Agregar imagen</h2><p>Se almacenará de forma privada y la API resolverá su acceso.</p></div><button type="button" className="icon-button" onClick={() => setAddingMedia(false)}><X size={18} /></button></div><div className="form-grid edit-grid"><Field label="Archivo de imagen" wide><input type="file" accept="image/jpeg,image/png,image/webp,image/gif" onChange={(event) => { const file = event.target.files?.[0] || null; const error = file ? imageFileError(file) : null; if (error) { event.target.value = ''; setMediaForm({ ...mediaForm, file: null }); notify(error, 'error'); return } setMediaForm({ ...mediaForm, file }) }} required /><small className="field-help">JPEG, PNG, WebP o GIF · máximo 10 MB</small></Field><Field label="Texto alternativo"><input value={mediaForm.altText} onChange={(e) => setMediaForm({ ...mediaForm, altText: e.target.value })} placeholder="Ej. Alimento para perro adulto" required /></Field><Field label="Variante específica"><select value={mediaForm.variantId} onChange={(e) => setMediaForm({ ...mediaForm, variantId: e.target.value })}><option value="">Imagen general</option>{product.variants.map((item) => <option key={item.id} value={item.id}>{formatPresentation(item.presentation, item.weightGrams)}</option>)}</select></Field><Field label="Orden"><input inputMode="numeric" value={mediaForm.displayOrder} onChange={(e) => setMediaForm({ ...mediaForm, displayOrder: e.target.value.replace(/\D/g, '') })} /></Field></div><div className="form-actions"><button type="button" className="button ghost" onClick={() => setAddingMedia(false)}>Cancelar</button><button className="button primary" disabled={busy || !mediaForm.file}>{busy ? 'Subiendo…' : 'Subir imagen'}</button></div></form>}
    {editingMedia && <form className="panel edit-panel" onSubmit={saveMedia}><div className="panel-heading"><div><h2>Editar imagen</h2><p>Actualizá su descripción, variante y orden de aparición.</p></div><button type="button" className="icon-button" onClick={() => setEditingMedia(null)}><X size={18} /></button></div><div className="form-grid edit-grid"><Field label="Texto alternativo"><input autoFocus value={mediaEditForm.altText} onChange={(event) => setMediaEditForm({ ...mediaEditForm, altText: event.target.value })} required /></Field><Field label="Variante específica"><select value={mediaEditForm.variantId} onChange={(event) => setMediaEditForm({ ...mediaEditForm, variantId: event.target.value })}><option value="">Imagen general</option>{product.variants.map((item) => <option key={item.id} value={item.id}>{formatPresentation(item.presentation, item.weightGrams)}</option>)}</select></Field><Field label="Orden"><input inputMode="numeric" value={mediaEditForm.displayOrder} onChange={(event) => setMediaEditForm({ ...mediaEditForm, displayOrder: event.target.value.replace(/\D/g, '') })} /></Field></div><div className="form-actions"><button type="button" className="button danger" disabled={busy} onClick={() => void deleteMedia(editingMedia)}>Eliminar imagen</button><div className="push-actions"><button type="button" className="button ghost" onClick={() => setEditingMedia(null)}>Cancelar</button><button className="button primary" disabled={busy}>Guardar cambios</button></div></div></form>}
    {editingGuide && <form className="panel edit-panel" onSubmit={saveGuide}><div className="panel-heading"><div><h2>Guía de alimentación</h2><p>Reemplaza la guía vigente usada por la calculadora pública.</p></div><button type="button" className="icon-button" onClick={() => setEditingGuide(false)}><X size={18} /></button></div><div className="form-grid edit-grid"><Field label="Fuente"><input value={guideForm.sourceLabel} onChange={(e) => setGuideForm({ ...guideForm, sourceLabel: e.target.value })} placeholder="Ej. Tabla del fabricante" required /></Field><Field label="URL de la fuente"><input type="url" value={guideForm.sourceUrl} onChange={(e) => setGuideForm({ ...guideForm, sourceUrl: e.target.value })} placeholder="Opcional" /></Field></div><div className="guide-entries">{guideForm.entries.map((entry, index) => <div className="guide-row" key={index}><Field label="Peso mascota (kg)"><input inputMode="decimal" value={entry.petWeightKg} onChange={(e) => setGuideForm({ ...guideForm, entries: guideForm.entries.map((item, i) => i === index ? { ...item, petWeightKg: e.target.value } : item) })} required /></Field><Field label="Etapa"><input value={entry.lifeStage} onChange={(e) => setGuideForm({ ...guideForm, entries: guideForm.entries.map((item, i) => i === index ? { ...item, lifeStage: e.target.value } : item) })} placeholder="Opcional" /></Field><Field label="Gramos mín."><input inputMode="decimal" value={entry.dailyGramsMin} onChange={(e) => setGuideForm({ ...guideForm, entries: guideForm.entries.map((item, i) => i === index ? { ...item, dailyGramsMin: e.target.value } : item) })} required /></Field><Field label="Gramos máx."><input inputMode="decimal" value={entry.dailyGramsMax} onChange={(e) => setGuideForm({ ...guideForm, entries: guideForm.entries.map((item, i) => i === index ? { ...item, dailyGramsMax: e.target.value } : item) })} required /></Field>{guideForm.entries.length > 1 && <button type="button" className="icon-button" onClick={() => setGuideForm({ ...guideForm, entries: guideForm.entries.filter((_, i) => i !== index) })}><X size={16} /></button>}</div>)}</div><div className="guide-actions"><button type="button" className="button secondary" onClick={() => setGuideForm({ ...guideForm, entries: [...guideForm.entries, { petWeightKg: '', lifeStage: '', dailyGramsMin: '', dailyGramsMax: '' }] })}><Plus size={15} /> Agregar tramo</button></div><div className="form-actions"><button type="button" className="button ghost" onClick={() => setEditingGuide(false)}>Cancelar</button><button className="button primary" disabled={busy}>Guardar guía</button></div></form>}
    <div className="detail-grid"><section className="panel information-card"><div className="panel-heading"><h2>Información</h2><div className="panel-actions"><button className="button small secondary" onClick={openEditing}><Pencil size={14} /> Editar</button><button className="text-button" onClick={() => setEditingGuide(true)}>Configurar guía</button></div></div><div className="info-rows"><Info label="Categoría" value={product.category?.name || 'Sin categoría'} /><Info label="Marca" value={product.brand.name} /><Info label="Especie" value={product.species || 'Sin especificar'} /><Info label="Etapa" value={product.lifeStage || 'Sin especificar'} /></div><div className="description-block"><span>Descripción</span><p>{product.description || 'Este producto todavía no tiene una descripción.'}</p></div></section><section className="panel product-media-panel"><div className="panel-heading"><div><h2>Imágenes</h2><p>{product.media?.length || 0} asociadas al producto.</p></div><button className="button small secondary" onClick={() => setAddingMedia(true)}><Plus size={14} /> Agregar</button></div>{product.media?.length ? <div className="media-gallery">{[...product.media].sort((a, b) => a.displayOrder - b.displayOrder).map((media) => <article key={media.id}><img src={media.url} alt={media.altText} /><div><strong>{media.altText}</strong><small>{media.variantId ? formatPresentation(product.variants.find((item) => item.id === media.variantId)?.presentation || null, product.variants.find((item) => item.id === media.variantId)?.weightGrams) : 'Imagen general'} · orden {media.displayOrder}</small></div><button className="icon-button" title="Editar imagen" onClick={() => startMediaEdit(media)}><Pencil size={15} /></button></article>)}</div> : <div className="product-placeholder"><Package size={48} /><span>Sin imagen</span><small>Requerida para activar el producto.</small><button className="button primary" onClick={() => setAddingMedia(true)}><Plus size={15} /> Agregar imagen</button></div>}</section></div>
    {addingVariant && <form className="panel inline-operation" onSubmit={addVariant}><div><h2>Nueva variante</h2><p>Creá el SKU; luego podrás asociar ofertas y calcular su precio.</p></div><Field label="SKU"><input value={variantForm.sku} onChange={(e) => setVariantForm({ ...variantForm, sku: e.target.value })} placeholder="EXC-ADULT-15" /></Field><Field label="Presentación"><input value={variantForm.presentation} onChange={(e) => setVariantForm({ ...variantForm, presentation: e.target.value })} placeholder="15 kg" /></Field><Field label="Peso en gramos"><input inputMode="numeric" value={variantForm.weightGrams} onChange={(e) => setVariantForm({ ...variantForm, weightGrams: e.target.value.replace(/\D/g, '') })} placeholder="15000" /></Field><label className="check-field"><input type="checkbox" checked={variantForm.active} onChange={(e) => setVariantForm({ ...variantForm, active: e.target.checked })} /> Activa</label><div className="inline-actions"><button type="button" className="button ghost" onClick={() => setAddingVariant(false)}>Cancelar</button><button className="button primary" disabled={busy}>Agregar</button></div></form>}
    <section className="panel table-panel variants-panel"><div className="panel-heading"><div><h2>Variantes</h2><p>{product.variants.length} presentaciones asociadas.</p></div><button className="button secondary" onClick={() => setAddingVariant(true)}><Plus size={16} /> Agregar variante</button></div><div className="table-wrap"><table><thead><tr><th>SKU</th><th>Presentación</th><th>Precio</th><th>Proveedor</th><th>Estado</th><th /></tr></thead><tbody>{product.variants.map((variant) => { const offer = getPreferredOffer(variant, data.offers); const supplier = data.suppliers.find((s) => s.id === offer?.supplierId); return <tr key={variant.id} onClick={() => openVariant(variant.id, product.id)}><td className="mono">{variant.sku || '—'}</td><td>{formatPresentation(variant.presentation, variant.weightGrams)}</td><td className="strong-cell">{money(variant.salePrice)}</td><td>{supplier?.name || <span className="danger-text">Sin proveedor</span>}</td><td><StatusBadge status={variant.active ? 'ACTIVE' : 'DRAFT'} /></td><td><ChevronRight size={17} /></td></tr>})}</tbody></table></div></section>
  </>
}

function SkuDetail({ variant, data, navigate, mutate, notify }: { variant: Variant; data: DataState; navigate: (view: View) => void; mutate: (fn: (d: DataState) => DataState) => void; notify: (m: string, k?: ToastKind) => void }) {
  const product = data.products.find((p) => p.id === variant.productId)!
  const variantOffers = data.offers.filter((o) => o.variantId === variant.id)
  const [offerId, setOfferId] = useState(getPreferredOffer(variant, data.offers)?.id || '')
  const [calculation, setCalculation] = useState<{ recommendedPrice: string; commercialPrice: string; breakdown: PricingBreakdown } | null>(null)
  const [busy, setBusy] = useState(false)
  const [editingVariant, setEditingVariant] = useState(false)
  const [editingInventory, setEditingInventory] = useState(false)
  const [offerMode, setOfferMode] = useState<'new' | 'edit' | null>(null)
  const [variantForm, setVariantForm] = useState({ sku: variant.sku || '', presentation: variant.presentation || '', weightGrams: variant.weightGrams?.toString() || '', compareAtPrice: variant.compareAtPrice || '', active: variant.active, preferredSupplierOfferId: variant.preferredSupplierOfferId || '' })
  const [offerForm, setOfferForm] = useState({ supplierId: '', supplierSku: '', unitCost: '', stockStatus: 'AVAILABLE' as Offer['stockStatus'], leadTimeHours: '', minimumQuantity: '1' })
  const [inventoryForm, setInventoryForm] = useState({ quantityDelta: '', reason: '' })
  const [movements, setMovements] = useState<InventoryMovement[]>([])
  const [movementsError, setMovementsError] = useState('')
  const selectedOffer = variantOffers.find((o) => o.id === offerId)
  const supplier = data.suppliers.find((s) => s.id === selectedOffer?.supplierId)
  const replaceVariant = (updated: Variant) => mutate((current) => ({ ...current, products: current.products.map((item) => ({ ...item, variants: item.variants.map((candidate) => candidate.id === variant.id ? updated : candidate) })) }))
  const saveVariant = async (event: FormEvent) => { event.preventDefault(); setBusy(true); try { const payload = { sku: variantForm.sku || null, presentation: variantForm.presentation || null, weightGrams: variantForm.weightGrams ? Number(variantForm.weightGrams) : null, compareAtPrice: variantForm.compareAtPrice || null, active: variantForm.active, preferredSupplierOfferId: variantForm.preferredSupplierOfferId || null }; const updated = await api.updateVariant(variant.id, payload); replaceVariant(updated); setEditingVariant(false); notify('SKU actualizado correctamente.') } catch (error) { notify((error as Error).message, 'error') } finally { setBusy(false) } }
  const loadMovements = async () => { try { setMovementsError(''); setMovements(await api.inventoryMovements(variant.id)) } catch (error) { setMovementsError((error as Error).message) } }
  useEffect(() => { void loadMovements() }, [variant.id])
  const saveInventory = async (event: FormEvent) => { event.preventDefault(); setBusy(true); try { const quantityDelta = Number(inventoryForm.quantityDelta); const saved = await api.adjustInventory(variant.id, { quantityDelta, reason: inventoryForm.reason }); replaceVariant({ ...variant, onHand: saved.onHand, reserved: saved.reserved, availableQuantity: saved.available }); setInventoryForm({ quantityDelta: '', reason: '' }); setEditingInventory(false); await loadMovements(); notify(`Ajuste registrado: ${saved.available} unidades disponibles.`) } catch (error) { notify((error as Error).message, 'error') } finally { setBusy(false) } }
  const beginOffer = (mode: 'new' | 'edit') => { if (mode === 'edit' && selectedOffer) setOfferForm({ supplierId: selectedOffer.supplierId, supplierSku: selectedOffer.supplierSku || '', unitCost: selectedOffer.unitCost, stockStatus: selectedOffer.stockStatus, leadTimeHours: selectedOffer.leadTimeHours?.toString() || '', minimumQuantity: selectedOffer.minimumQuantity.toString() }); else setOfferForm({ supplierId: '', supplierSku: '', unitCost: '', stockStatus: 'AVAILABLE', leadTimeHours: '', minimumQuantity: '1' }); setOfferMode(mode) }
  const saveOffer = async (event: FormEvent) => { event.preventDefault(); setBusy(true); try { const common = { supplierSku: offerForm.supplierSku || null, unitCost: offerForm.unitCost, stockStatus: offerForm.stockStatus, leadTimeHours: offerForm.leadTimeHours ? Number(offerForm.leadTimeHours) : null, minimumQuantity: Number(offerForm.minimumQuantity || 1) }; let saved: Offer; if (offerMode === 'edit' && selectedOffer) saved = await api.updateOffer(selectedOffer.id, common); else saved = await api.createOffer({ supplierId: offerForm.supplierId, variantId: variant.id, ...common }); mutate((current) => ({ ...current, offers: offerMode === 'edit' ? current.offers.map((item) => item.id === saved.id ? saved : item) : [...current.offers, saved] })); setOfferId(saved.id); setOfferMode(null); setCalculation(null); notify(offerMode === 'edit' ? 'Oferta actualizada.' : 'Oferta asociada al SKU.') } catch (error) { notify((error as Error).message, 'error') } finally { setBusy(false) } }
  const recalculate = async () => { setBusy(true); try { setCalculation((await api.calculate(variant.id, offerId)).calculation); notify('Precio recalculado con la oferta seleccionada.') } catch (e) { notify((e as Error).message, 'error') } finally { setBusy(false) } }
  const apply = async () => { if (!calculation) return; setBusy(true); try { const review = await api.recalculate(variant.id); await api.applyPrice(variant.id, review.id); mutate((current) => ({ ...current, products: current.products.map((p) => ({ ...p, variants: p.variants.map((v) => v.id === variant.id ? { ...v, salePrice: calculation.commercialPrice } : v) })) })); notify(`Precio ${money(calculation.commercialPrice)} aplicado al SKU.`) } catch (e) { notify((e as Error).message, 'error') } finally { setBusy(false) } }
  return <><PageHeader eyebrow={`${product.name} · ${product.brand.name}`} title={formatPresentation(variant.presentation, variant.weightGrams)} description={`SKU ${variant.sku || 'sin código'}`} back={() => navigate('product')} actions={<><StatusBadge status={variant.active ? 'ACTIVE' : 'DRAFT'} /><button className="button secondary" onClick={() => setEditingInventory(!editingInventory)}><Boxes size={16} /> Inventario</button><button className="button secondary" onClick={() => setEditingVariant(!editingVariant)}>Editar SKU</button></>} />
    {editingVariant && <form className="panel edit-panel" onSubmit={saveVariant}><div className="panel-heading"><div><h2>Editar variante</h2><p>Identificación, presentación y disponibilidad del SKU.</p></div><button type="button" className="icon-button" onClick={() => setEditingVariant(false)}><X size={18} /></button></div><div className="form-grid edit-grid"><Field label="SKU"><input className="mono-input" value={variantForm.sku} onChange={(e) => setVariantForm({ ...variantForm, sku: e.target.value })} /></Field><Field label="Presentación"><input value={variantForm.presentation} onChange={(e) => setVariantForm({ ...variantForm, presentation: e.target.value })} /></Field><Field label="Peso en gramos"><input inputMode="numeric" value={variantForm.weightGrams} onChange={(e) => setVariantForm({ ...variantForm, weightGrams: e.target.value.replace(/\D/g, '') })} /></Field><Field label="Precio de comparación"><input inputMode="decimal" value={variantForm.compareAtPrice} onChange={(e) => setVariantForm({ ...variantForm, compareAtPrice: e.target.value })} placeholder="Opcional" /></Field><Field label="Oferta preferida"><select value={variantForm.preferredSupplierOfferId} onChange={(e) => setVariantForm({ ...variantForm, preferredSupplierOfferId: e.target.value })}><option value="">Selección automática</option>{variantOffers.map((offer) => <option key={offer.id} value={offer.id}>{data.suppliers.find((item) => item.id === offer.supplierId)?.name} · {money(offer.unitCost)}</option>)}</select></Field><label className="check-field form-check"><input type="checkbox" checked={variantForm.active} onChange={(e) => setVariantForm({ ...variantForm, active: e.target.checked })} /> SKU activo</label></div><div className="form-actions"><button type="button" className="button ghost" onClick={() => setEditingVariant(false)}>Cancelar</button><button className="button primary" disabled={busy}>{busy ? 'Guardando…' : 'Guardar SKU'}</button></div></form>}
    {editingInventory && <form className="panel edit-panel" onSubmit={saveInventory}><div className="panel-heading"><div><h2>Ajustar inventario</h2><p>Sumá o descontá existencia física. Las reservas se administran desde los pedidos.</p></div><button type="button" className="icon-button" onClick={() => setEditingInventory(false)}><X size={18} /></button></div><div className="form-grid edit-grid"><Field label="Ajuste de unidades"><input autoFocus type="number" value={inventoryForm.quantityDelta} onChange={(event) => setInventoryForm({ ...inventoryForm, quantityDelta: event.target.value })} placeholder="Ej. 10 o -2" required /></Field><Field label="Motivo"><input value={inventoryForm.reason} onChange={(event) => setInventoryForm({ ...inventoryForm, reason: event.target.value })} placeholder="Recepción, rotura, corrección…" required /></Field></div><div className="inventory-readonly"><Info label="Existencia actual" value={variant.onHand ?? '—'} /><Info label="Reservadas" value={variant.reserved ?? '—'} /><Info label="Disponibles" value={variant.availableQuantity ?? '—'} /></div><div className="form-actions end"><button className="button primary" disabled={busy || !inventoryForm.quantityDelta || !inventoryForm.reason.trim()}>{busy ? 'Registrando…' : 'Registrar ajuste'}</button></div></form>}
    {offerMode && <form className="panel edit-panel" onSubmit={saveOffer}><div className="panel-heading"><div><h2>{offerMode === 'edit' ? 'Editar oferta' : 'Nueva oferta de proveedor'}</h2><p>Costo, disponibilidad y condiciones de reposición.</p></div><button type="button" className="icon-button" onClick={() => setOfferMode(null)}><X size={18} /></button></div><div className="form-grid edit-grid"><Field label="Proveedor"><select disabled={offerMode === 'edit'} value={offerForm.supplierId} onChange={(e) => setOfferForm({ ...offerForm, supplierId: e.target.value })} required><option value="">Seleccionar proveedor</option>{data.suppliers.filter((item) => item.active).map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></Field><Field label="SKU del proveedor"><input value={offerForm.supplierSku} onChange={(e) => setOfferForm({ ...offerForm, supplierSku: e.target.value })} /></Field><Field label="Costo unitario"><input inputMode="decimal" value={offerForm.unitCost} onChange={(e) => setOfferForm({ ...offerForm, unitCost: e.target.value.replace(/[^\d.]/g, '') })} required /></Field><Field label="Disponibilidad"><select value={offerForm.stockStatus} onChange={(e) => setOfferForm({ ...offerForm, stockStatus: e.target.value as Offer['stockStatus'] })}><option value="AVAILABLE">Disponible</option><option value="ON_REQUEST">A pedido</option><option value="OUT_OF_STOCK">Sin stock</option><option value="UNKNOWN">Desconocido</option></select></Field><Field label="Lead time en horas"><input inputMode="numeric" value={offerForm.leadTimeHours} onChange={(e) => setOfferForm({ ...offerForm, leadTimeHours: e.target.value.replace(/\D/g, '') })} /></Field><Field label="Cantidad mínima"><input inputMode="numeric" value={offerForm.minimumQuantity} onChange={(e) => setOfferForm({ ...offerForm, minimumQuantity: e.target.value.replace(/\D/g, '') })} required /></Field></div><div className="form-actions"><button type="button" className="button ghost" onClick={() => setOfferMode(null)}>Cancelar</button><button className="button primary" disabled={busy || !offerForm.unitCost || (!offerForm.supplierId && offerMode === 'new')}>{busy ? 'Guardando…' : 'Guardar oferta'}</button></div></form>}
    <div className="sku-summary"><SummaryItem label="Precio de venta" value={money(variant.salePrice)} icon={<CircleDollarSign size={19} />} /><SummaryItem label="Margen actual" value={percentage(marginFor(variant, data.offers))} icon={<BarChart3 size={19} />} /><SummaryItem label="Proveedor" value={supplier?.name || 'Sin proveedor'} icon={<Building2 size={19} />} /><SummaryItem label="Costo proveedor" value={money(selectedOffer?.unitCost)} icon={<Tags size={19} />} /><SummaryItem label="Disponibilidad" value={variant.availableQuantity ? `${variant.availableQuantity} en stock` : stockLabel(selectedOffer?.stockStatus)} icon={<Boxes size={19} />} /><SummaryItem label="Lead time" value={selectedOffer?.leadTimeHours != null ? `${selectedOffer.leadTimeHours} horas` : '—'} icon={<Clock3 size={19} />} /></div>
    <div className="sku-grid"><section className="panel calculator"><div className="panel-heading"><div><h2>Calculadora de precio</h2><p>Costos y reglas activas para esta variante.</p></div><span className="rule-version">Reglas v{data.rules.active?.version || '—'}</span></div>{calculation ? <><div className="breakdown"><CostRow label="Costo mercadería" value={calculation.breakdown.productCost} /><CostRow label="Fulfillment" value={calculation.breakdown.fulfillment} /><CostRow label="Packaging" value={calculation.breakdown.packaging} /><CostRow label="Comisión estimada" value={calculation.breakdown.paymentVariable} /><CostRow label="Logística absorbida" value={calculation.breakdown.subsidizedShipping} /><CostRow label="Otros" value={calculation.breakdown.other} /><CostRow label="Costo total" value={calculation.breakdown.effectiveCost} total /></div><div className="price-result"><div><span>Margen objetivo</span><strong>{data.rules.active?.targetMarginPercent || '—'}%</strong></div><div><span>Precio recomendado</span><strong>{money(calculation.recommendedPrice)}</strong></div><div className="commercial"><span>Precio comercial sugerido</span><strong>{money(calculation.commercialPrice)}</strong></div></div></> : <div className="empty-state compact"><CircleDollarSign size={27} /><strong>Listo para calcular</strong><p>Seleccioná una oferta disponible y recalculá.</p></div>}<div className="calculator-actions"><button className="button secondary" disabled={busy || !selectedOffer} onClick={recalculate}><RefreshCw size={16} /> {busy ? 'Calculando…' : 'Recalcular'}</button><button className="button primary" disabled={busy || !calculation} onClick={apply}><Check size={16} /> Aplicar {money(calculation?.commercialPrice)}</button></div></section>
      <section className="panel offers-panel"><div className="panel-heading"><div><h2>Ofertas de proveedores</h2><p>Elegí la base para el cálculo.</p></div><button className="button small secondary" onClick={() => beginOffer('new')}><Plus size={14} /> Nueva</button></div>{variantOffers.length ? <><div className="offer-list">{variantOffers.map((offer) => { const sup = data.suppliers.find((s) => s.id === offer.supplierId); return <button className={offerId === offer.id ? 'selected' : ''} key={offer.id} onClick={() => setOfferId(offer.id)}><span className="radio">{offerId === offer.id && <span />}</span><span><strong>{sup?.name}</strong><small>{stockLabel(offer.stockStatus)} · {offer.leadTimeHours ? `${offer.leadTimeHours}h` : 'sin lead time'}</small></span><b>{money(offer.unitCost)}</b></button>})}</div>{selectedOffer && <div className="offer-footer"><button className="text-button" onClick={() => beginOffer('edit')}>Editar oferta seleccionada</button></div>}</> : <div className="empty-state compact"><Building2 size={27} /><strong>Sin ofertas asociadas</strong><p>Asociá una oferta para poder calcular el precio.</p><button className="button primary" onClick={() => beginOffer('new')}><Plus size={15} /> Agregar oferta</button></div>}</section></div>
    <section className="panel table-panel inventory-history"><div className="panel-heading"><div><h2>Movimientos de inventario</h2><p>Reservas, despachos, liberaciones y ajustes del SKU.</p></div><button className="button small secondary" onClick={() => void loadMovements()}><RefreshCw size={14} /> Actualizar</button></div>{movementsError ? <div className="inline-error"><AlertTriangle size={16} />{movementsError}</div> : movements.length ? <div className="table-wrap"><table><thead><tr><th>Fecha</th><th>Tipo</th><th>Cantidad</th><th>Motivo</th><th>Pedido</th></tr></thead><tbody>{movements.map((movement) => <tr key={movement.id}><td>{new Date(movement.createdAt).toLocaleString('es-AR')}</td><td>{movement.type}</td><td className={movement.quantity < 0 ? 'danger-text' : 'success-text'}>{movement.quantity > 0 ? '+' : ''}{movement.quantity}</td><td>{movement.reason || '—'}</td><td className="mono">{movement.orderId || '—'}</td></tr>)}</tbody></table></div> : <div className="empty-state compact"><Boxes size={27} /><strong>Sin movimientos</strong><p>Todavía no hay actividad de inventario para este SKU.</p></div>}</section>
  </>
}

function Suppliers({ data, mutate, notify, openSupplier }: { data: DataState; mutate: (fn: (d: DataState) => DataState) => void; notify: (m: string, k?: ToastKind) => void; openSupplier: (id: string) => void }) {
  const [query, setQuery] = useState(''); const [adding, setAdding] = useState(false); const [name, setName] = useState(''); const [busy, setBusy] = useState(false)
  const items = data.suppliers.filter((s) => s.name.toLowerCase().includes(query.toLowerCase()))
  const save = async (event: FormEvent) => { event.preventDefault(); setBusy(true); try { const supplier = await api.createSupplier({ name, active: true }); mutate((d) => ({ ...d, suppliers: [...d.suppliers, supplier] })); setName(''); setAdding(false); notify('Proveedor creado correctamente.') } catch (error) { notify((error as Error).message, 'error') } finally { setBusy(false) } }
  return <><PageHeader eyebrow="Abastecimiento" title="Proveedores" description={`${data.suppliers.filter(s => s.active).length} proveedores activos`} actions={<button className="button primary" onClick={() => setAdding(true)}><Plus size={17} /> Nuevo proveedor</button>} />{adding && <form className="inline-create panel" onSubmit={save}><label>Nombre del proveedor<input autoFocus value={name} onChange={(e) => setName(e.target.value)} placeholder="Ej. Distribuidora Norte" required /></label><button type="button" className="button ghost" onClick={() => setAdding(false)}>Cancelar</button><button className="button primary" disabled={busy}>Guardar</button></form>}<section className="panel table-panel"><div className="filters"><label className="search-field"><Search size={17} /><input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Buscar proveedor" /></label></div><div className="table-wrap"><table><thead><tr><th>Proveedor</th><th>SKU asociados</th><th>Disponibles</th><th>Lead time promedio</th><th>Estado</th><th /></tr></thead><tbody>{items.map((supplier) => { const offers = data.offers.filter(o => o.supplierId === supplier.id); const leads = offers.map(o => o.leadTimeHours).filter((v): v is number => v !== null); return <tr key={supplier.id} onClick={() => openSupplier(supplier.id)}><td><div className="product-cell"><span className="product-thumb supplier"><Building2 size={19} /></span><span><strong>{supplier.name}</strong><small>Proveedor comercial</small></span></div></td><td>{offers.length}</td><td>{offers.filter(o => o.stockStatus === 'AVAILABLE').length}</td><td>{leads.length ? `${Math.round(leads.reduce((a,b) => a+b, 0)/leads.length)} horas` : '—'}</td><td><StatusBadge status={supplier.active ? 'ACTIVE' : 'ARCHIVED'} /></td><td><ChevronRight size={17} /></td></tr>})}</tbody></table></div></section></>
}

function SupplierDetail({ supplier, data, navigate, openVariant, mutate, notify }: { supplier: Supplier; data: DataState; navigate: (view: View) => void; openVariant: (id: string, productId?: string) => void; mutate: (fn: (d: DataState) => DataState) => void; notify: (m: string, k?: ToastKind) => void }) {
  const offers = data.offers.filter((o) => o.supplierId === supplier.id); const [editing, setEditing] = useState(false); const [editingOffer, setEditingOffer] = useState<Offer | null>(null); const [addingOffer, setAddingOffer] = useState(false); const [busy, setBusy] = useState(false); const [supplierForm, setSupplierForm] = useState({ name: supplier.name, active: supplier.active }); const [offerForm, setOfferForm] = useState({ variantId: '', supplierSku: '', unitCost: '', stockStatus: 'AVAILABLE' as Offer['stockStatus'], leadTimeHours: '', minimumQuantity: '1' })
  const variantContext = (id: string) => { for (const product of data.products) { const variant = product.variants.find((v) => v.id === id); if (variant) return { product, variant } } return null }
  const startOffer = (offer?: Offer) => { setEditingOffer(offer || null); setAddingOffer(true); setOfferForm(offer ? { variantId: offer.variantId, supplierSku: offer.supplierSku || '', unitCost: offer.unitCost, stockStatus: offer.stockStatus, leadTimeHours: offer.leadTimeHours?.toString() || '', minimumQuantity: offer.minimumQuantity.toString() } : { variantId: '', supplierSku: '', unitCost: '', stockStatus: 'AVAILABLE', leadTimeHours: '', minimumQuantity: '1' }) }
  const saveSupplier = async (event: FormEvent) => { event.preventDefault(); setBusy(true); try { const updated = await api.updateSupplier(supplier.id, supplierForm); mutate((current) => ({ ...current, suppliers: current.suppliers.map((item) => item.id === supplier.id ? updated : item) })); setEditing(false); notify('Proveedor actualizado.') } catch (error) { notify((error as Error).message, 'error') } finally { setBusy(false) } }
  const saveOffer = async (event: FormEvent) => { event.preventDefault(); setBusy(true); try { const common = { supplierSku: offerForm.supplierSku || null, unitCost: offerForm.unitCost, stockStatus: offerForm.stockStatus, leadTimeHours: offerForm.leadTimeHours ? Number(offerForm.leadTimeHours) : null, minimumQuantity: Number(offerForm.minimumQuantity || 1) }; const saved = editingOffer ? await api.updateOffer(editingOffer.id, common) : await api.createOffer({ supplierId: supplier.id, variantId: offerForm.variantId, ...common }); mutate((current) => ({ ...current, offers: editingOffer ? current.offers.map((item) => item.id === saved.id ? saved : item) : [...current.offers, saved] })); setAddingOffer(false); setEditingOffer(null); notify(editingOffer ? 'Oferta actualizada.' : 'SKU asociado al proveedor.') } catch (error) { notify((error as Error).message, 'error') } finally { setBusy(false) } }
  return <><PageHeader eyebrow="Proveedor" title={supplier.name} description="Condiciones comerciales y productos asociados." back={() => navigate('suppliers')} actions={<><StatusBadge status={supplier.active ? 'ACTIVE' : 'ARCHIVED'} /><button className="button secondary" onClick={() => setEditing(!editing)}>Editar proveedor</button></>} />
    {editing && <form className="panel edit-panel" onSubmit={saveSupplier}><div className="panel-heading"><div><h2>Editar proveedor</h2><p>Nombre y disponibilidad comercial.</p></div><button type="button" className="icon-button" onClick={() => setEditing(false)}><X size={18} /></button></div><div className="form-grid edit-grid"><Field label="Nombre"><input value={supplierForm.name} onChange={(e) => setSupplierForm({ ...supplierForm, name: e.target.value })} required /></Field><label className="check-field form-check"><input type="checkbox" checked={supplierForm.active} onChange={(e) => setSupplierForm({ ...supplierForm, active: e.target.checked })} /> Proveedor activo</label></div><div className="form-actions"><button type="button" className="button ghost" onClick={() => setEditing(false)}>Cancelar</button><button className="button primary" disabled={busy}>Guardar proveedor</button></div></form>}
    {addingOffer && <form className="panel edit-panel" onSubmit={saveOffer}><div className="panel-heading"><div><h2>{editingOffer ? 'Editar oferta' : 'Asociar SKU'}</h2><p>Condiciones de compra para este proveedor.</p></div><button type="button" className="icon-button" onClick={() => setAddingOffer(false)}><X size={18} /></button></div><div className="form-grid edit-grid"><Field label="Producto y variante"><select disabled={Boolean(editingOffer)} value={offerForm.variantId} onChange={(e) => setOfferForm({ ...offerForm, variantId: e.target.value })} required><option value="">Seleccionar SKU</option>{data.products.flatMap((product) => product.variants.map((variant) => <option key={variant.id} value={variant.id}>{product.name} · {formatPresentation(variant.presentation, variant.weightGrams)} · {variant.sku || 'sin SKU'}</option>))}</select></Field><Field label="SKU del proveedor"><input value={offerForm.supplierSku} onChange={(e) => setOfferForm({ ...offerForm, supplierSku: e.target.value })} /></Field><Field label="Costo unitario"><input inputMode="decimal" value={offerForm.unitCost} onChange={(e) => setOfferForm({ ...offerForm, unitCost: e.target.value.replace(/[^\d.]/g, '') })} required /></Field><Field label="Disponibilidad"><select value={offerForm.stockStatus} onChange={(e) => setOfferForm({ ...offerForm, stockStatus: e.target.value as Offer['stockStatus'] })}><option value="AVAILABLE">Disponible</option><option value="ON_REQUEST">A pedido</option><option value="OUT_OF_STOCK">Sin stock</option><option value="UNKNOWN">Desconocido</option></select></Field><Field label="Lead time en horas"><input inputMode="numeric" value={offerForm.leadTimeHours} onChange={(e) => setOfferForm({ ...offerForm, leadTimeHours: e.target.value.replace(/\D/g, '') })} /></Field><Field label="Cantidad mínima"><input inputMode="numeric" value={offerForm.minimumQuantity} onChange={(e) => setOfferForm({ ...offerForm, minimumQuantity: e.target.value.replace(/\D/g, '') })} required /></Field></div><div className="form-actions"><button type="button" className="button ghost" onClick={() => setAddingOffer(false)}>Cancelar</button><button className="button primary" disabled={busy || !offerForm.unitCost || (!offerForm.variantId && !editingOffer)}>{busy ? 'Guardando…' : 'Guardar oferta'}</button></div></form>}
    <div className="supplier-facts"><Info label="Ofertas registradas" value={offers.length} /><Info label="Ofertas disponibles" value={offers.filter((item) => item.stockStatus === 'AVAILABLE').length} /><Info label="Pedido mínimo" value={offers.length ? `${Math.min(...offers.map(o => o.minimumQuantity))} unidad` : '—'} /><Info label="Estado" value={supplier.active ? 'Activo' : 'Inactivo'} /></div><section className="panel table-panel"><div className="panel-heading"><div><h2>Productos asociados</h2><p>{offers.length} ofertas activas o registradas.</p></div><button className="button primary" onClick={() => startOffer()}><Plus size={16} /> Asociar SKU</button></div><div className="table-wrap"><table><thead><tr><th>SKU</th><th>Producto</th><th>Costo</th><th>Disponible</th><th>Lead time</th><th /></tr></thead><tbody>{offers.map((offer) => { const ctx = variantContext(offer.variantId); if (!ctx) return null; return <tr key={offer.id} onClick={() => openVariant(ctx.variant.id, ctx.product.id)}><td className="mono">{ctx.variant.sku}</td><td><strong>{ctx.product.name}</strong><br /><small>{formatPresentation(ctx.variant.presentation, ctx.variant.weightGrams)}</small></td><td className="strong-cell">{money(offer.unitCost)}</td><td><StockBadge status={offer.stockStatus} /></td><td>{offer.leadTimeHours != null ? `${offer.leadTimeHours}h` : '—'}</td><td><button className="icon-button" title="Editar oferta" onClick={(event) => { event.stopPropagation(); startOffer(offer) }}><MoreHorizontal size={18} /></button></td></tr>})}</tbody></table></div>{!offers.length && <div className="empty-state compact"><Building2 size={27} /><strong>Sin productos asociados</strong><p>Creá la primera oferta para este proveedor.</p><button className="button primary" onClick={() => startOffer()}><Plus size={15} /> Asociar SKU</button></div>}</section></>
}

function Prices({ data, mutate, notify, openVariant }: { data: DataState; mutate: (fn: (d: DataState) => DataState) => void; notify: (m: string, k?: ToastKind) => void; openVariant: (id: string, productId?: string) => void }) {
  const rows = data.products.flatMap((product) => product.variants.map((variant) => ({ product, variant, recommended: recommendedFor(variant, data.offers, data), margin: marginFor(variant, data.offers) }))).filter((row) => row.recommended && (!row.variant.salePrice || Math.abs(Number(row.variant.salePrice) - Number(row.recommended)) > 100))
  const [applying, setApplying] = useState<string | null>(null)
  const apply = async (variant: Variant, recommended: number) => { setApplying(variant.id); try { let finalPrice = commercialFor(recommended); const review = await api.recalculate(variant.id); await api.applyPrice(variant.id, review.id); finalPrice = Number(review.commercialPrice); mutate((d) => ({ ...d, products: d.products.map((p) => ({ ...p, variants: p.variants.map((v) => v.id === variant.id ? { ...v, salePrice: String(finalPrice) } : v) })) })); notify(`Nuevo precio aplicado: ${money(finalPrice)}.`) } catch (e) { notify((e as Error).message, 'error') } finally { setApplying(null) } }
  return <><PageHeader eyebrow="Rentabilidad" title="Precios a revisar" description="Cambios sugeridos según costos y margen objetivo." /><section className="panel table-panel"><div className="panel-heading pricing-heading"><div><h2>{rows.length} ajustes pendientes</h2><p>Revisá cada recomendación antes de aplicarla.</p></div><span className="rule-version">Margen objetivo {data.rules.active?.targetMarginPercent || '—'}%</span></div><div className="table-wrap"><table><thead><tr><th>Producto</th><th>Actual</th><th>Recomendado</th><th>Variación</th><th>Margen actual</th><th /></tr></thead><tbody>{rows.map(({ product, variant, recommended, margin }) => { const commercial = commercialFor(Number(recommended)); const diff = variant.salePrice ? ((commercial - Number(variant.salePrice)) / Number(variant.salePrice)) * 100 : null; return <tr key={variant.id}><td onClick={() => openVariant(variant.id, product.id)}><div className="product-cell"><span className="product-thumb"><Package size={19} /></span><span><strong>{product.name} · {variant.presentation}</strong><small>{variant.sku}</small></span></div></td><td>{money(variant.salePrice)}</td><td className="strong-cell recommended">{money(commercial)}</td><td><span className="delta">{diff == null ? 'Nuevo' : `${diff > 0 ? '+' : ''}${diff.toFixed(1)}%`}</span></td><td className={margin !== null && margin < Number(data.rules.active?.targetMarginPercent || 25) ? 'danger-text' : ''}>{percentage(margin)} {margin !== null && margin < Number(data.rules.active?.targetMarginPercent || 25) && <AlertTriangle size={14} />}</td><td><button className="button small secondary" disabled={applying === variant.id} onClick={() => void apply(variant, Number(recommended))}>{applying === variant.id ? 'Aplicando…' : 'Aplicar recomendado'}</button></td></tr>})}</tbody></table></div>{!rows.length && <div className="empty-state"><Check size={30} /><strong>Todos los precios están al día</strong><p>No hay diferencias relevantes para revisar.</p></div>}</section></>
}

function References({ type, data, mutate, notify }: { type: 'brands' | 'categories'; data: DataState; mutate: (fn: (d: DataState) => DataState) => void; notify: (m: string, k?: ToastKind) => void }) {
  const list = type === 'brands' ? data.brands : data.categories; const singular = type === 'brands' ? 'marca' : 'categoría'; const [adding, setAdding] = useState(false); const [name, setName] = useState(''); const [busy, setBusy] = useState(false); const [logoUploading, setLogoUploading] = useState<string | null>(null); const [editing, setEditing] = useState<Reference | null>(null); const [editForm, setEditForm] = useState({ name: '', slug: '', description: '', seoTitle: '', seoDescription: '', displayOrder: '0', active: true })
  const save = async (e: FormEvent) => { e.preventDefault(); setBusy(true); try { const created = await api.createReference(type, { name, active: true }); mutate((d) => ({ ...d, [type]: [...d[type], created] })); setName(''); setAdding(false); notify(`${singular[0].toUpperCase() + singular.slice(1)} creada.`) } catch (err) { notify((err as Error).message, 'error') } finally { setBusy(false) } }
  const startEdit = (item: Reference) => { setEditing(item); setEditForm({ name: item.name, slug: item.slug, description: item.description || '', seoTitle: item.seoTitle || '', seoDescription: item.seoDescription || '', displayOrder: String(item.displayOrder || 0), active: item.active }) }
  const saveEdit = async (event: FormEvent) => { event.preventDefault(); if (!editing) return; setBusy(true); try { const payload = { name: editForm.name, slug: editForm.slug, description: editForm.description || null, seoTitle: editForm.seoTitle || null, seoDescription: editForm.seoDescription || null, displayOrder: Number(editForm.displayOrder || 0), active: editForm.active }; const updated = await api.updateReference(type, editing.id, payload); mutate((current) => ({ ...current, [type]: current[type].map((item) => item.id === editing.id ? updated : item) })); setEditing(null); notify(`${singular[0].toUpperCase() + singular.slice(1)} actualizada.`) } catch (error) { notify((error as Error).message, 'error') } finally { setBusy(false) } }
  const uploadLogo = async (brand: Reference, file: File) => { const error = imageFileError(file); if (error) { notify(error, 'error'); return } setLogoUploading(brand.id); try { const updated = await api.uploadBrandLogo(brand.id, file); mutate((current) => ({ ...current, brands: current.brands.map((item) => item.id === brand.id ? updated : item) })); notify(`Logo de ${brand.name} actualizado.`) } catch (cause) { notify((cause as Error).message, 'error') } finally { setLogoUploading(null) } }
  return <><PageHeader eyebrow="Catálogo" title={type === 'brands' ? 'Marcas' : 'Categorías'} description={`${list.length} ${type} registradas`} actions={<button className="button primary" onClick={() => setAdding(true)}><Plus size={17} /> Nueva {singular}</button>} />{adding && <form className="inline-create panel" onSubmit={save}><label>Nombre de la {singular}<input autoFocus value={name} onChange={(e) => setName(e.target.value)} placeholder={type === 'brands' ? 'Ej. Excellent' : 'Ej. Alimento seco'} required /></label><button type="button" className="button ghost" onClick={() => setAdding(false)}>Cancelar</button><button className="button primary" disabled={busy}>Guardar</button></form>}{editing && <form className="panel edit-panel" onSubmit={saveEdit}><div className="panel-heading"><div><h2>Editar {singular}</h2><p>Información operativa y metadatos del catálogo público.</p></div><button type="button" className="icon-button" onClick={() => setEditing(null)}><X size={18} /></button></div><div className="form-grid edit-grid"><Field label="Nombre"><input autoFocus value={editForm.name} onChange={(e) => setEditForm({ ...editForm, name: e.target.value })} required /></Field><Field label="Slug"><input value={editForm.slug} onChange={(e) => setEditForm({ ...editForm, slug: e.target.value })} required /></Field><Field label="Orden"><input inputMode="numeric" value={editForm.displayOrder} onChange={(e) => setEditForm({ ...editForm, displayOrder: e.target.value.replace(/\D/g, '') })} /></Field><label className="check-field form-check"><input type="checkbox" checked={editForm.active} onChange={(e) => setEditForm({ ...editForm, active: e.target.checked })} /> Activa</label><Field label="Descripción" wide><textarea rows={3} value={editForm.description} onChange={(e) => setEditForm({ ...editForm, description: e.target.value })} /></Field><Field label="Título SEO"><input value={editForm.seoTitle} onChange={(e) => setEditForm({ ...editForm, seoTitle: e.target.value })} /></Field><Field label="Descripción SEO"><input value={editForm.seoDescription} onChange={(e) => setEditForm({ ...editForm, seoDescription: e.target.value })} /></Field></div><div className="form-actions"><button type="button" className="button ghost" onClick={() => setEditing(null)}>Cancelar</button><button className="button primary" disabled={busy}>Guardar cambios</button></div></form>}<section className="reference-grid">{list.map((item) => <article className="panel reference-card" key={item.id}><span className={`reference-icon ${item.logoUrl ? 'has-logo' : ''}`}>{item.logoUrl ? <img src={item.logoUrl} alt={`Logo de ${item.name}`} /> : type === 'brands' ? <Tags size={20} /> : <Package size={20} />}</span><div><strong>{item.name}</strong><small>/{item.slug}</small>{type === 'brands' && <label className="logo-upload">{logoUploading === item.id ? 'Subiendo…' : item.logoUrl ? 'Reemplazar logo' : 'Subir logo'}<input type="file" accept="image/jpeg,image/png,image/webp,image/gif" disabled={logoUploading === item.id} onChange={(event) => { const file = event.target.files?.[0]; if (file) void uploadLogo(item, file); event.target.value = '' }} /></label>}</div><StatusBadge status={item.active ? 'ACTIVE' : 'ARCHIVED'} /><button className="icon-button" title={`Editar ${singular}`} onClick={() => startEdit(item)}><MoreHorizontal size={18} /></button></article>)}</section></>
}

function NewProduct({ data, navigate, mutate, notify, openProduct }: { data: DataState; navigate: (view: View) => void; mutate: (fn: (d: DataState) => DataState) => void; notify: (m: string, k?: ToastKind) => void; openProduct: (id: string) => void }) {
  const [step, setStep] = useState(1); const [busy, setBusy] = useState(false)
  const [form, setForm] = useState({ brandId: '', name: '', categoryId: '', species: 'Perro', description: '', presentation: '', sku: '', supplierId: '', unitCost: '', leadTimeHours: '48', imageAlt: '' })
  const [imageFile, setImageFile] = useState<File | null>(null)
  const update = (key: keyof typeof form, value: string) => setForm((f) => ({ ...f, [key]: value }))
  const recommended = form.unitCost ? (Number(form.unitCost) + Number(data.rules.active?.fulfillmentCost || 0) + Number(data.rules.active?.packagingCost || 0) + Number(data.rules.active?.paymentFixedCost || 0) + Number(data.rules.active?.subsidizedShippingCost || 0) + Number(data.rules.active?.otherCost || 0)) / (1 - (Number(data.rules.active?.paymentFeePercent || 0) + Number(data.rules.active?.taxPercent || 0) + Number(data.rules.active?.targetMarginPercent || 0)) / 100) : null
  const price = recommended ? commercialFor(recommended) : null
  const save = async (publish: boolean) => {
    setBusy(true)
    try {
      let product = await api.createProduct({ name: form.name, brandId: form.brandId, categoryId: form.categoryId, species: form.species, description: form.description })
      const variant = await api.createVariant(product.id, { sku: form.sku, presentation: form.presentation, active: publish })
      let createdOffer: Offer | null = null
      if (form.supplierId && form.unitCost) createdOffer = await api.createOffer({ supplierId: form.supplierId, variantId: variant.id, unitCost: form.unitCost, stockStatus: 'AVAILABLE', leadTimeHours: Number(form.leadTimeHours) })
      const createdMedia = imageFile && form.imageAlt ? await api.uploadProductMedia(product.id, { file: imageFile, altText: form.imageAlt, displayOrder: 0 }) : null
      if (publish) {
        const review = await api.recalculate(variant.id)
        await api.applyPrice(variant.id, review.id)
        variant.salePrice = review.commercialPrice
        product = await api.updateProduct(product.id, { status: 'ACTIVE' })
      }
      product.variants = [variant]
      product.media = createdMedia ? [createdMedia] : product.media
      mutate((current) => ({ ...current, products: [...current.products, product], offers: createdOffer ? [...current.offers, createdOffer] : current.offers }))
      notify(publish ? 'Producto publicado correctamente.' : 'Borrador guardado.')
      openProduct(product.id)
    } catch (error) { notify((error as Error).message, 'error') } finally { setBusy(false) }
  }
  return <>
    <PageHeader eyebrow="Catálogo" title="Nuevo producto" description="Creá el producto y su primera variante en dos pasos." back={() => navigate('products')} />
    <div className="stepper"><div className={step >= 1 ? 'active' : ''}><span>{step > 1 ? <Check size={15} /> : '1'}</span><p><strong>Información</strong><small>Datos del producto</small></p></div><i /><div className={step >= 2 ? 'active' : ''}><span>2</span><p><strong>Variante y costo</strong><small>SKU, proveedor e imagen</small></p></div></div>
    <section className="panel form-panel">
      {step === 1 ? <div className="form-content"><div className="section-title"><h2>Información del producto</h2><p>Los datos que identifican el producto en el catálogo.</p></div><div className="form-grid"><Field label="Marca"><select value={form.brandId} onChange={(e) => update('brandId', e.target.value)} required><option value="">Seleccionar marca</option>{data.brands.filter((item) => item.active).map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></Field><Field label="Nombre"><input value={form.name} onChange={(e) => update('name', e.target.value)} placeholder="Ej. Adult" /></Field><Field label="Categoría"><select value={form.categoryId} onChange={(e) => update('categoryId', e.target.value)}><option value="">Seleccionar categoría</option>{data.categories.filter((item) => item.active).map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></Field><Field label="Especie"><select value={form.species} onChange={(e) => update('species', e.target.value)}><option>Perro</option><option>Gato</option></select></Field><Field label="Descripción" wide><textarea value={form.description} onChange={(e) => update('description', e.target.value)} placeholder="Descripción breve del producto…" rows={4} /></Field></div></div> :
        <div className="form-content"><div className="section-title"><h2>Primera variante</h2><p>Definí el SKU, su oferta inicial y la imagen requerida para publicar.</p></div><div className="form-grid"><Field label="Presentación"><input value={form.presentation} onChange={(e) => update('presentation', e.target.value)} placeholder="Ej. 15 kg" /></Field><Field label="SKU"><input className="mono-input" value={form.sku} onChange={(e) => update('sku', e.target.value)} placeholder="EXC-ADULT-15" /></Field><Field label="Proveedor"><select value={form.supplierId} onChange={(e) => update('supplierId', e.target.value)}><option value="">Seleccionar proveedor</option>{data.suppliers.filter((item) => item.active).map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></Field><Field label="Costo proveedor"><div className="money-input"><span>$</span><input inputMode="numeric" value={form.unitCost} onChange={(e) => update('unitCost', e.target.value.replace(/\D/g, ''))} placeholder="51.200" /></div></Field><Field label="Lead time"><div className="suffix-input"><input inputMode="numeric" value={form.leadTimeHours} onChange={(e) => update('leadTimeHours', e.target.value.replace(/\D/g, ''))} /><span>horas</span></div></Field><Field label="Archivo de imagen"><input type="file" accept="image/jpeg,image/png,image/webp,image/gif" onChange={(event) => { const file = event.target.files?.[0] || null; const error = file ? imageFileError(file) : null; if (error) { event.target.value = ''; setImageFile(null); notify(error, 'error'); return } setImageFile(file) }} /><small className="field-help">JPEG, PNG, WebP o GIF · máximo 10 MB</small></Field><Field label="Texto alternativo"><input value={form.imageAlt} onChange={(e) => update('imageAlt', e.target.value)} placeholder="Bolsa de alimento…" /></Field></div>{price && <div className="instant-price"><span className="instant-icon"><CircleDollarSign size={22} /></span><div><small>Precio comercial sugerido</small><strong>{money(price)}</strong></div><div><small>Margen objetivo</small><strong>{data.rules.active?.targetMarginPercent || '—'}%</strong></div><span className="success-note"><Check size={14} /> Calculado con reglas activas</span></div>}</div>}
      <div className="form-actions">{step === 1 ? <><button className="button ghost" onClick={() => navigate('products')}>Cancelar</button><button className="button primary" disabled={!form.name || !form.brandId || !form.categoryId} onClick={() => setStep(2)}>Continuar <ArrowRight size={16} /></button></> : <><button className="button ghost" onClick={() => setStep(1)}><ArrowLeft size={16} /> Volver</button><div className="push-actions"><button className="button secondary" disabled={busy || !form.sku || !form.presentation} onClick={() => void save(false)}>Guardar borrador</button><button className="button primary" disabled={busy || !form.sku || !form.presentation || !form.unitCost || !form.supplierId || !imageFile || !form.imageAlt} onClick={() => void save(true)}>{busy ? 'Guardando…' : 'Publicar'}</button></div></>}</div>
    </section>
  </>
}

function PricingSettings({ data, mutate, notify }: { data: DataState; mutate: (fn: (d: DataState) => DataState) => void; notify: (m: string, k?: ToastKind) => void }) {
  const active = data.rules.active; const source = data.rules.draft || active; const [values, setValues] = useState({ fulfillmentCost: source?.fulfillmentCost || '', packagingCost: source?.packagingCost || '', paymentFixedCost: source?.paymentFixedCost || '', paymentFeePercent: source?.paymentFeePercent || '', subsidizedShippingCost: source?.subsidizedShippingCost || '', taxPercent: source?.taxPercent || '', otherCost: source?.otherCost || '', targetMarginPercent: source?.targetMarginPercent || '' }); const [busy, setBusy] = useState(false); const [history, setHistory] = useState<PricingRules[]>([]); const [historyError, setHistoryError] = useState('')
  const loadHistory = async () => { try { setHistoryError(''); setHistory(await api.ruleHistory()) } catch (error) { setHistoryError((error as Error).message) } }
  useEffect(() => { void loadHistory() }, [data.rules.active?.id, data.rules.draft?.id])
  const save = async () => { setBusy(true); try { const draft = await api.updateRules(values); mutate((d) => ({ ...d, rules: { ...d.rules, draft } })); notify('Reglas de precio guardadas como borrador.') } catch (e) { notify((e as Error).message, 'error') } finally { setBusy(false) } }
  const activate = async () => { if (!data.rules.draft) return; setBusy(true); try { const activated = await api.activateRules(); mutate((current) => ({ ...current, rules: { active: activated, draft: null } })); notify(`Reglas v${activated.version} activadas. Las nuevas recomendaciones ya usan esta configuración.`) } catch (error) { notify((error as Error).message, 'error') } finally { setBusy(false) } }
  return <><PageHeader eyebrow="Configuración" title="Reglas de precio" description="Costos globales usados para recomendar precios comerciales." actions={<><span className="rule-version">Activa v{active?.version || '—'}</span>{data.rules.draft && <button className="button primary" disabled={busy} onClick={() => void activate()}><Check size={16} /> Activar borrador v{data.rules.draft.version}</button>}</>} /><section className="panel form-panel settings-form"><div className="section-title"><h2>Estructura de costos</h2><p>{data.rules.draft ? `Editando borrador v${data.rules.draft.version}.` : 'Los importes se expresan en pesos argentinos por unidad.'}</p></div><div className="form-grid">{([['fulfillmentCost', 'Fulfillment'], ['packagingCost', 'Packaging'], ['paymentFixedCost', 'Comisión fija'], ['paymentFeePercent', 'Comisión variable (%)'], ['subsidizedShippingCost', 'Logística absorbida'], ['taxPercent', 'Impuestos (%)'], ['otherCost', 'Otros costos'], ['targetMarginPercent', 'Margen objetivo (%)']] as const).map(([key, label]) => <Field key={key} label={label}><input inputMode="decimal" value={values[key]} onChange={(e) => setValues(v => ({ ...v, [key]: e.target.value }))} required /></Field>)}</div><div className="settings-note"><AlertTriangle size={17} /><p><strong>Los cambios no alteran precios automáticamente.</strong><br />Primero se guardan como borrador; al activarlos generan nuevas recomendaciones para revisar.</p></div><div className="form-actions end"><button className="button primary" disabled={busy} onClick={() => void save()}>{busy ? 'Guardando…' : 'Guardar borrador'}</button></div></section><section className="panel table-panel rule-history"><div className="panel-heading"><div><h2>Historial de reglas</h2><p>Versiones activas, reemplazadas y borradores.</p></div><button className="button small secondary" onClick={() => void loadHistory()}><RefreshCw size={14} /> Actualizar</button></div>{historyError ? <div className="inline-error"><AlertTriangle size={16} />{historyError}</div> : <div className="table-wrap"><table><thead><tr><th>Versión</th><th>Estado</th><th>Margen objetivo</th><th>Creada</th><th>Activada</th></tr></thead><tbody>{history.map((rules) => <tr key={rules.id}><td className="strong-cell">v{rules.version}</td><td><StatusBadge status={rules.status} /></td><td>{rules.targetMarginPercent || '—'}%</td><td>{rules.createdAt ? new Date(rules.createdAt).toLocaleString('es-AR') : '—'}</td><td>{rules.activatedAt ? new Date(rules.activatedAt).toLocaleString('es-AR') : '—'}</td></tr>)}</tbody></table></div>}</section></>
}

function Select({ value, onChange, options }: { value: string; onChange: (v: string) => void; options: string[][] }) { return <label className="select-field"><select value={value} onChange={(e) => onChange(e.target.value)}>{options.map(([v, label]) => <option value={v} key={v}>{label}</option>)}</select><ChevronDown size={15} /></label> }
function StatusBadge({ status }: { status: string }) { const map: Record<string, string> = { ACTIVE: 'Activo', DRAFT: 'Borrador', ARCHIVED: 'Archivado' }; return <span className={`status-badge ${status.toLowerCase()}`}><i />{map[status] || status}</span> }
function StockBadge({ status }: { status: Offer['stockStatus'] }) { return <span className={`stock-badge ${status.toLowerCase()}`}>{stockLabel(status)}</span> }
function stockLabel(status?: Offer['stockStatus']) { return ({ AVAILABLE: 'Disponible', OUT_OF_STOCK: 'Sin stock', ON_REQUEST: 'A pedido', UNKNOWN: 'Desconocido' } as Record<string, string>)[status || 'UNKNOWN'] }
function Info({ label, value }: { label: string; value: ReactNode }) { return <div className="info-item"><span>{label}</span><strong>{value}</strong></div> }
function SummaryItem({ label, value, icon }: { label: string; value: ReactNode; icon: ReactNode }) { return <div className="summary-item"><span className="summary-icon">{icon}</span><div><small>{label}</small><strong>{value}</strong></div></div> }
function CostRow({ label, value, total }: { label: string; value: string; total?: boolean }) { return <div className={total ? 'total' : ''}><span>{label}</span><strong>{money(value)}</strong></div> }
function Field({ label, children, wide }: { label: string; children: ReactNode; wide?: boolean }) { return <label className={wide ? 'wide' : ''}><span>{label}</span>{children}</label> }
function NotFound({ navigate }: { navigate: (view: View) => void }) { return <section className="panel empty-state"><Package size={30} /><strong>No encontramos este registro</strong><p>Puede haber sido eliminado o la dirección ya no es válida.</p><button className="button primary" onClick={() => navigate('products')}>Volver al catálogo</button></section> }
function LoadingScreen() { return <div className="loading-screen"><div className="brand-mark large"><img src="/brand/patitas-isotipo.png" alt="" /></div><span className="spinner" /><p>Conectando con Patitas…</p></div> }
